import * as T from './three.module.js';import {growthProgress} from './growth.js?v=simulation15';
export function createOrchard(x,z,{rows=2,cols=4,spacing=5}={}){const root=new T.Group(),trees=[],bark=new T.MeshStandardMaterial({color:'#796343',roughness:1}),leaf=new T.MeshStandardMaterial({color:'#64824a',roughness:.95}),species=['Apple','Pear','Orange','Plum'];root.name='Separate apple, pear, orange and plum rows';const trunkGeo=new T.CylinderGeometry(.14,.26,2.3,8),leafGeo=new T.SphereGeometry(1,8,6),fruitGeo=new T.SphereGeometry(.14,8,6);
 for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){const type=row*cols+col,kind=type%4,tree=new T.Group(),canopy=new T.Group(),fruit=new T.Group();tree.position.set(x+(col-(cols-1)/2)*spacing,.25,z+(row-(rows-1)/2)*spacing*1.4);root.add(tree);tree.name=species[kind]+' tree';const trunk=new T.Mesh(trunkGeo,bark);trunk.position.y=1.15;tree.add(trunk,canopy,fruit);
 const crown=new T.InstancedMesh(leafGeo,leaf,5),dummy=new T.Object3D();for(let j=0;j<5;j++){const a=j*2.4;dummy.position.set(Math.sin(a)*.75,2.6+(kind===1?j*.26:Math.sin(j)*.35),Math.cos(a)*.75);dummy.scale.set(kind===1?.85:1.15,kind===1?1.25:.8,1);dummy.updateMatrix();crown.setMatrixAt(j,dummy.matrix);}crown.computeBoundingSphere();canopy.add(crown);
 const f=new T.InstancedMesh(fruitGeo,new T.MeshStandardMaterial({color:['#b95b48','#bdd06b','#de9c42','#775176'][kind],roughness:.7}),18);for(let j=0;j<18;j++){const a=j*2.4;dummy.position.set(Math.sin(a)*(1+(j%3)*.1),2.3+(j%4)*.22,Math.cos(a)*1.1);dummy.scale.set(1,kind===1?1.7:kind===3?1.2:1,kind===1?.85:1);dummy.updateMatrix();f.setMatrixAt(j,dummy.matrix);}f.computeBoundingSphere();fruit.add(f);fruit.visible=false;trees.push({tree,fruit});}
 return {root,trees,update(record,day,now=Date.now()){root.visible=!!record?.established;if(!root.visible)return;const age=record.treePlantedAt===undefined?1:growthProgress({startedAt:record.treePlantedAt,startedDay:record.treePlantedDay,readyDay:record.treePlantedDay+3,durationMs:72*3600000},day,now),p=growthProgress(record.job,day,now);for(const {tree,fruit}of trees){tree.scale.setScalar(.16+.84*age);fruit.visible=!!record.job&&p>.25;fruit.scale.setScalar(.15+.85*p);}}};}
export function createFieldCrop(x,z,w,d){const root=new T.Group();root.name='Planted maize rows';const count=48,stem=new T.InstancedMesh(new T.CylinderGeometry(.04,.055,1.7,5),new T.MeshStandardMaterial({color:'#789a4c'}),count),leaves=new T.InstancedMesh(new T.SphereGeometry(1,6,4),new T.MeshStandardMaterial({color:'#628543'}),count*3),ears=new T.InstancedMesh(new T.SphereGeometry(.11,6,4),new T.MeshStandardMaterial({color:'#d4be6d'}),count),dummy=new T.Object3D();for(let i=0;i<count;i++){const px=x+((i%8)/7-.5)*(w-3),pz=z+(Math.floor(i/8)/5-.5)*(d-3);dummy.position.set(px,.85,pz);dummy.scale.setScalar(1);dummy.rotation.set(0,0,0);dummy.updateMatrix();stem.setMatrixAt(i,dummy.matrix);for(let j=0;j<3;j++){dummy.position.set(px+Math.sin(j*2)*.2,.4+j*.35,pz);dummy.scale.set(.45,.065,.15);dummy.rotation.set(0,j*2,.3);dummy.updateMatrix();leaves.setMatrixAt(i*3+j,dummy.matrix);}dummy.position.set(px+.1,1.2,pz);dummy.scale.set(.7,2,.7);dummy.rotation.set(0,0,.2);dummy.updateMatrix();ears.setMatrixAt(i,dummy.matrix);}for(const m of [stem,leaves,ears]){m.computeBoundingSphere();root.add(m);}root.position.y=.3;return root;}
